"""Inspect the Word template structure."""

from docx import Document
import re

def inspect_template(filepath):
    """Analyze a template document for placeholders and structure."""
    doc = Document(filepath)

    print("Template Analysis:")
    print("=" * 70)

    # Find all unique placeholders and conditionals
    placeholders = set()
    conditional_blocks = []

    print("\n--- PARAGRAPHS ---")
    for i, para in enumerate(doc.paragraphs):
        if para.text.strip():
            print(f"{i:3d}: {para.text}")

            # Find placeholders
            placeholders.update(re.findall(r'\{\{[A-Z_]+\}\}', para.text))

            # Find conditional markers
            if 'IF_' in para.text or 'END_IF' in para.text:
                conditional_blocks.append((i, para.text))

    print("\n--- TABLES ---")
    for i, table in enumerate(doc.tables):
        print(f"\nTable {i}: {len(table.rows)} rows x {len(table.columns)} columns")
        for row_idx, row in enumerate(table.rows):
            for cell_idx, cell in enumerate(row.cells):
                cell_text = cell.text.strip()
                if cell_text:
                    print(f"  [{row_idx},{cell_idx}]: {cell_text}")
                    placeholders.update(re.findall(r'\{\{[A-Z_]+\}\}', cell_text))

    print("\n" + "=" * 70)
    print(f"\nPLACEHOLDERS FOUND ({len(placeholders)}):")
    for p in sorted(placeholders):
        print(f"  - {p}")

    print(f"\nCONDITIONAL BLOCKS:")
    for idx, text in conditional_blocks:
        print(f"  Line {idx}: {text}")

    return doc, placeholders, conditional_blocks

if __name__ == '__main__':
    doc, placeholders, conditionals = inspect_template('/root/offer_letter_template.docx')

