#!/usr/bin/env python3
"""Fill offer letter template with employee data."""

import json
from docx import Document
import re


def replace_in_paragraph(paragraph, replacements):
    """Replace placeholders in a paragraph while preserving formatting."""
    for key, value in replacements.items():
        if key in paragraph.text:
            # Process each run
            for run in paragraph.runs:
                if key in run.text:
                    run.text = run.text.replace(key, str(value))


def process_conditionals(doc, conditions):
    """
    Process conditional blocks in the document.
    Removes conditional markers and content based on conditions.
    """
    paragraphs_to_remove = []
    inside_false_conditional = False
    current_condition = None

    for i, para in enumerate(doc.paragraphs):
        text = para.text

        # Check for IF markers
        if_match = re.search(r'\{\{IF_([A-Z_]+)\}\}', text)
        if if_match:
            condition_name = if_match.group(1)
            current_condition = condition_name

            # Check if condition is met
            if conditions.get(condition_name, False):
                # Keep content but remove the IF marker
                inside_false_conditional = False
                # Remove the IF marker from the paragraph
                for run in para.runs:
                    run.text = run.text.replace(f'{{{{IF_{condition_name}}}}}', '')
            else:
                # Remove this paragraph and mark to skip until END
                inside_false_conditional = True
                paragraphs_to_remove.append(i)
            continue

        # Check for END_IF markers
        end_match = re.search(r'\{\{END_IF_([A-Z_]+)\}\}', text)
        if end_match:
            condition_name = end_match.group(1)

            if inside_false_conditional and condition_name == current_condition:
                # This is the end of a false block, mark for removal
                paragraphs_to_remove.append(i)
                inside_false_conditional = False
                current_condition = None
            else:
                # This is the end of a true block, remove the END marker
                for run in para.runs:
                    run.text = run.text.replace(f'{{{{END_IF_{condition_name}}}}}', '')
            continue

        # If we're inside a false conditional, mark for removal
        if inside_false_conditional:
            paragraphs_to_remove.append(i)

    # Remove marked paragraphs in reverse order
    for idx in sorted(set(paragraphs_to_remove), reverse=True):
        p_element = doc.paragraphs[idx]._element
        p_element.getparent().remove(p_element)


def replace_in_table(table, replacements):
    """Replace placeholders in all table cells."""
    for row in table.rows:
        for cell in row.cells:
            # Process paragraphs in the cell
            for para in cell.paragraphs:
                replace_in_paragraph(para, replacements)

            # Process nested tables
            for nested_table in cell.tables:
                replace_in_table(nested_table, replacements)


def fill_template(template_path, data_path, output_path):
    """Fill the template with data from JSON file."""

    # Load data
    with open(data_path, 'r') as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    # Prepare conditions for conditional blocks
    conditions = {
        'RELOCATION': data.get('RELOCATION_PACKAGE', 'No').upper() == 'YES'
    }

    # Process conditional blocks FIRST (before replacements)
    process_conditionals(doc, conditions)

    # Prepare replacements dictionary
    replacements = {}
    for key, value in data.items():
        # Skip fields used for conditionals only
        if key == 'RELOCATION_PACKAGE':
            continue
        # Create placeholder format
        placeholder = f'{{{{{key}}}}}'
        replacements[placeholder] = str(value)

    # Replace in all paragraphs
    for para in doc.paragraphs:
        replace_in_paragraph(para, replacements)

    # Replace in all tables (including nested)
    for table in doc.tables:
        replace_in_table(table, replacements)

    # Save the filled document
    doc.save(output_path)
    print(f"Offer letter saved to: {output_path}")


if __name__ == '__main__':
    fill_template(
        template_path='/root/offer_letter_template.docx',
        data_path='/root/employee_data.json',
        output_path='/root/offer_letter_filled.docx'
    )
    print("\nTemplate filled successfully!")
    print("Relocation package: INCLUDED (RELOCATION_PACKAGE = Yes)")

