from docx import Document
import re


def verify_document(filepath):
    """Check if all placeholders have been replaced."""
    doc = Document(filepath)

    print("FILLED OFFER LETTER - VERIFICATION")
    print("=" * 70)

    # Check for remaining placeholders
    remaining_placeholders = set()
    conditional_markers = set()

    print("\n--- CONTENT ---\n")
    for i, para in enumerate(doc.paragraphs):
        if para.text.strip():
            print(para.text)

            # Find any remaining placeholders
            placeholders = re.findall(r'\{\{[A-Z_]+\}\}', para.text)
            for p in placeholders:
                if 'IF_' in p or 'END_IF' in p:
                    conditional_markers.add(p)
                else:
                    remaining_placeholders.add(p)

    # Check tables
    print("\n--- TABLES ---\n")
    for table_idx, table in enumerate(doc.tables):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    if para.text.strip():
                        print(para.text)

                        placeholders = re.findall(r'\{\{[A-Z_]+\}\}', para.text)
                        for p in placeholders:
                            if 'IF_' in p or 'END_IF' in p:
                                conditional_markers.add(p)
                            else:
                                remaining_placeholders.add(p)

                # Check nested tables
                for nested_table in cell.tables:
                    print(f"\n  Nested Table:")
                    for nested_row in nested_table.rows:
                        row_text = ' | '.join([c.text for c in nested_row.cells])
                        print(f"    {row_text}")

                        for c in nested_row.cells:
                            placeholders = re.findall(r'\{\{[A-Z_]+\}\}', c.text)
