    else:
        print("\n✓ All data placeholders filled successfully!")

    if conditional_markers:
        print(f"\n⚠️  REMAINING CONDITIONAL MARKERS ({len(conditional_markers)}):")
        for m in sorted(conditional_markers):
            print(f"  - {m}")
    else:
        print("✓ All conditional markers processed correctly!")

    return len(remaining_placeholders) == 0 and len(conditional_markers) == 0


