                            placeholders = re.findall(r'\{\{[A-Z_]+\}\}', c.text)
                            for p in placeholders:
                                if 'IF_' in p or 'END_IF' in p:
                                    conditional_markers.add(p)
                                else:
                                    remaining_placeholders.add(p)

    print("\n" + "=" * 70)
    print("\nVERIFICATION RESULTS:")

    if remaining_placeholders:
        print(f"\n⚠️  UNFILLED PLACEHOLDERS ({len(remaining_placeholders)}):")
        for p in sorted(remaining_placeholders):
            print(f"  - {p}")
    else:
        print("\n✓ All data placeholders filled successfully!")

    if conditional_markers:
        print(f"\n⚠️  REMAINING CONDITIONAL MARKERS ({len(conditional_markers)}):")
        for m in sorted(conditional_markers):
            print(f"  - {m}")
    else:
        print("✓ All conditional markers processed correctly!")

    return len(remaining_placeholders) == 0 and len(conditional_markers) == 0


if __name__ == '__main__':
    success = verify_document('/root/offer_letter_filled.docx')
    if success:
        print("\n✓ Document is ready for delivery!")
    else:
        print("\n⚠️  Document needs attention.")

